C=['#40c4ff','#aa6eeb','#ff785a','#ffa028','#50dc96','#f05aaa']
def mc(q,answer,d1,d2,d3,fb):return dict(t='mcq',q=q,a=[answer,d1,d2,d3],fb=fb)
def sort(q,items,cats,fb):return dict(t='sort',q=q,items=items,cats=cats,fb=fb)
def match(q,pairs,fb):return dict(t='match',q=q,pairs=pairs,fb=fb)
def multi(q,yes,no,fb):return dict(t='multi',q=q,opts=[yes[0],no[0],yes[1],no[1]],correct=yes,fb=fb)
def S(name,facts,challenge,answer,diagram,tasks,info):return dict(name=name,facts=facts,challenge=challenge,answer=answer,diagram=diagram,tasks=tasks,info=info)
def L(n,title,slug,mission,donow,outcomes,starter,starter_answer,terms,stations,final,final_answer,plenary):return dict(n=n,title=title,slug=slug,mission=mission,donow=donow,outcomes=outcomes,starter=starter,starter_answer=starter_answer,terms=terms,stations=stations,final=final,final_answer=final_answer,plenary=plenary)
